const b = $('Receive Contact Request').first().json.body || {};
const clip = (v, n) => String(v || '').trim().slice(0, n);
const transcript = (Array.isArray(b.transcript) ? b.transcript : []).slice(-40).map(m => ({ role: m.role === 'user' ? 'Guest' : 'Assistant', content: clip(m.content, 2000) })).filter(m => m.content);
return [{ json: {
  sessionId: clip(b.sessionId, 100) || 'unknown',
  name: clip(b.name, 120),
  phone: clip(b.phone, 60),
  email: clip(b.email, 200),
  unansweredQuestion: clip(b.unansweredQuestion, 2000) || '(not specified)',
  transcript,
  transcriptText: transcript.map(m => m.role + ': ' + m.content).join('\n') || '(no messages)'
}}];

