const d = $('Prepare Transcript').first().json;
const summary = String(($input.first().json || {}).text || '').trim() || 'Summary unavailable — see the full transcript below.';
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const rows = d.transcript.map(m => '<tr><td style="padding:8px 12px;vertical-align:top;font-weight:600;color:' + (m.role === 'Guest' ? '#0f766e' : '#475569') + ';white-space:nowrap">' + m.role + '</td><td style="padding:8px 12px;color:#0f172a">' + esc(m.content).replace(/\n/g,'<br>') + '</td></tr>').join('');
const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#0f172a">'
 + '<h2 style="margin:0 0 4px">New guest contact request</h2>'
 + '<p style="margin:0 0 20px;color:#64748b">Cincinnati Hotel chatbot · ' + new Date().toUTCString() + '</p>'
 + '<table style="border-collapse:collapse;margin-bottom:20px">'
 + '<tr><td style="padding:4px 12px 4px 0;color:#64748b">Name</td><td><b>' + esc(d.name) + '</b></td></tr>'
 + '<tr><td style="padding:4px 12px 4px 0;color:#64748b">Phone</td><td>' + esc(d.phone) + '</td></tr>'
 + '<tr><td style="padding:4px 12px 4px 0;color:#64748b">Email</td><td><a href="mailto:' + esc(d.email) + '">' + esc(d.email) + '</a></td></tr>'
 + '</table>'
 + '<div style="background:#fef3c7;border-left:4px solid #f59e0b;padding:12px 16px;margin-bottom:20px"><div style="font-size:12px;text-transform:uppercase;color:#92400e;letter-spacing:.05em">Unanswered question</div><div style="font-size:16px;margin-top:4px">' + esc(d.unansweredQuestion) + '</div></div>'
 + '<h3 style="margin:0 0 6px">Conversation summary</h3><p style="margin:0 0 20px;line-height:1.5">' + esc(summary) + '</p>'
 + '<h3 style="margin:0 0 6px">Full transcript</h3><table style="border-collapse:collapse;width:100%;background:#f8fafc;font-size:14px">' + (rows || '<tr><td style="padding:8px">(empty)</td></tr>') + '</table>'
 + '<p style="color:#94a3b8;font-size:12px;margin-top:20px">Session ID: ' + esc(d.sessionId) + '</p></div>';
return [{ json: { ...d, summary, subject: 'Guest contact request: ' + d.name + ' — ' + d.unansweredQuestion.slice(0, 60), html, submitted_at: new Date().toISOString() } }];
